UPDATE fm_system_task_attempt
SET STATUS = #{status,jdbcType=VARCHAR},
    COMPLETED_AT = #{now,jdbcType=TIMESTAMP},
    DURATION_MS = TIMESTAMPDIFF(MICROSECOND, STARTED_AT, #{now,jdbcType=TIMESTAMP}) DIV 1000,
    ERROR_CODE = #{errorCode,jdbcType=VARCHAR}
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND EXECUTION_OID = #{executionOid,jdbcType=CHAR}
  AND REQUEST_ID = #{requestId,jdbcType=VARCHAR}
  AND GENERATION = #{generation,jdbcType=INTEGER}
  AND STATUS = 'RUNNING'
  AND STARTED_AT <= #{now,jdbcType=TIMESTAMP}

  AND LEASE_UNTIL > #{now,jdbcType=TIMESTAMP}


  AND LEASE_UNTIL <= #{now,jdbcType=TIMESTAMP}

UPDATE fm_system_task_attempt
SET STATUS = 'CANCELLED',
    COMPLETED_AT = #{now,jdbcType=TIMESTAMP},
    DURATION_MS = TIMESTAMPDIFF(MICROSECOND, STARTED_AT, #{now,jdbcType=TIMESTAMP}) DIV 1000,
    ERROR_CODE = 'GROOVY_PROCESS_CANCELLED'
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND EXECUTION_OID = #{executionOid,jdbcType=CHAR}
  AND GENERATION = #{generation,jdbcType=INTEGER}
  AND STATUS = 'RUNNING'
  AND STARTED_AT <= #{now,jdbcType=TIMESTAMP}
